  legalEditorTitle: '1. Éditeur du site',
  legalEditor: 'Éditeur',
  legalEmail: 'Email',
  legalCountry: 'Pays',
  legalCountryMorocco: 'Maroc',
  legalServiceTitle: '2. Description du service',
  legalServiceDesc: 'BazNova est un service en ligne de génération de CV et lettres de motivation assistée par intelligence artificielle, disponible en 4 langues (français, anglais, arabe, espagnol) avec 3 modèles de mise en page et 2 formats de téléchargement (PDF, Word).',
  legalCguTitle: '3. Conditions Générales d\'Utilisation',
  legalCgu31Title: '3.1. Accès au service',
  legalCgu31Desc: 'L\'accès au service nécessite la création d\'un compte et le paiement d\'un abonnement (Plan Pro ou Plan Lifetime). Le service est accessible immédiatement après le paiement via notre partenaire de paiement : LemonSqueezy (EUR/USD, carte bancaire internationale, PayPal, Apple Pay, Google Pay).',
  legalCgu32Title: '3.2. Utilisation autorisée',
  legalCgu32Desc: 'Le service est destiné à un usage personnel et professionnel légitime. L\'utilisateur s\'engage à ne pas utiliser le service à des fins illicites, frauduleuses ou portant atteinte aux droits de tiers.',
  legalCgu33Title: '3.3. Propriété intellectuelle',
  legalCgu33Desc: 'Le nom "BazNova", le logo, le design, le code source et l\'ensemble du contenu du site sont la propriété exclusive de E-Society 2050. Toute reproduction, copie, modification, distribution ou utilisation du service ou de ses éléments sans autorisation écrite préalable est strictement interdite et constitue une contrefaçon punie par la loi.',
  legalCgu34Title: '3.4. Contenu généré',
  legalCgu34Desc: 'Les CV et lettres de motivation générés par l\'IA sont la propriété de l\'utilisateur. BazNova ne revendique aucun droit sur le contenu généré par ses utilisateurs.',
  legalCgu35Title: '3.5. Paiements et remboursements',
  legalCgu35Desc: 'Les paiements sont traités par notre partenaire de paiement agréé : LemonSqueezy (EUR/USD). Pour toute demande de remboursement, veuillez contacter le support via le bouton d\'aide sur le site.',
  legalCgu36Title: '3.6. Responsabilité',
  legalCgu36Desc: 'BazNova fournit un outil d\'aide à la rédaction. La qualité du résultat final dépend des informations fournies par l\'utilisateur. BazNova ne saurait être tenu responsable du contenu des documents générés ni de leur utilisation par l\'utilisateur.',
  legalDataTitle: '4. Protection des données personnelles',
  legalDataIntro: 'Conformément à la législation marocaine (Loi 09-08 relative à la protection des personnes physiques à l\'égard du traitement des données à caractère personnel), nous informons les utilisateurs que :',
  legalDataBullet1: 'Les données collectées (nom, email, informations de CV) sont utilisées uniquement pour le fonctionnement du service.',
  legalDataBullet2: 'Les données ne sont jamais vendues ou partagées avec des tiers.',
  legalDataBullet3: 'L\'utilisateur peut demander la suppression de ses données à tout moment en contactant le support.',
  legalDataBullet4: 'Les données sont stockées de manière sécurisée.',
  legalCopyrightTitle: '5. Droits d\'auteur',
  legalCopyrightDesc: '© 2026 BazNova — E-Society 2050. Tous droits réservés. La marque "BazNova" et l\'ensemble du service sont protégés par les lois marocaines et internationales sur la propriété intellectuelle (Convention de Berne). Toute violation sera poursuivie.',
  legalHostingTitle: '6. Hébergement',
  legalHostingDesc: 'Le site est hébergé par Vercel Inc., San Francisco, États-Unis.',
  legalContactTitle: '7. Contact',
  legalContactDesc: 'Pour toute question concernant ces mentions légales, veuillez contacter :',
