    // SEO & FAQ
    seoTitle: 'Frequently Asked Questions about BazNova — Resume, Cover Letter & ATS Score',
    faqTitle: 'Frequently Asked Questions',
    faqSubtitle: 'Everything you need to know about BazNova and our AI tools for your job search.',
    faqQ1: 'How does BazNova work to create a resume?',
    faqA1: 'BazNova uses advanced artificial intelligence to analyze your professional information and generate a tailored resume. Fill out the 4-step form (personal info, career goals, experience & education, skills), choose your template (Modern, Classic or Creative), and the AI writes an ATS-optimized professional resume in under 60 seconds.',
    faqQ2: 'What is the ATS score and why is it important?',
    faqA2: 'The ATS (Applicant Tracking System) score measures how compatible your resume is with the automated recruitment software used by over 75% of companies. BazNova analyzes your resume across 5 criteria: keywords & SEO, structure & format, experience & impact, skills match, and readability. A high score increases your chances of passing initial recruitment filters.',
    faqQ3: 'Can I create a resume in multiple languages?',
    faqA3: 'Yes! BazNova is available in 4 languages: French, English, Arabic, and Spanish. The AI adapts vocabulary, style, and formatting to each language. You can create your resume in your preferred language and even generate multilingual versions for international applications.',
    faqQ4: 'How much does BazNova cost?',
    faqA4: 'BazNova offers 5 paid plans: Starter at €9/month for students, Pro at €19/month for active job seekers (most popular), Career+ at €39/month for executives (includes Mobility & Global), Employer at €49/month for recruiters, and Enterprise with custom pricing for large companies. An Annual plan at €70/year is also available. A Free plan lets you discover the tool with 2 resumes/month. A REST API is available for developers.',
    faqQ5: 'Can I download my resume in PDF and Word?',
    faqA5: 'Absolutely! With Pro and Annual plans, you can download your resume in PDF (standard A4 format) and Word (.doc). Both formats are perfectly optimized for printing and email sharing. PDF preserves the layout, while Word allows for further editing.',
    faqQ6: 'How does the AI cover letter work?',
    faqA6: 'BazNova generates a personalized cover letter from your information and the target job posting. Enter the company name, position, recruiter, your motivations, and key strengths. The AI writes a persuasive letter, adapted to your chosen tone (formal, semi-formal, or dynamic), in just 30 seconds.',
    faqQ7: 'Is my personal data safe?',
    faqA7: 'Yes, your data security is our priority. Your information is encrypted and never shared with third parties. We use standard security protocols (HTTPS, data encryption at rest). You can delete your account and all your data at any time from your personal space.',
    faqQ8: 'Does BazNova work for international candidates?',
    faqA8: 'Yes! BazNova is designed for candidates worldwide. We support payments in Euros (EUR), US Dollars (USD), and British Pounds (GBP). Our service is accessible from 16 countries across Europe, Americas, Oceania, and the Gulf. Generated resumes are adapted to international standards and optimized for French and English-speaking recruiters.',
    trustTitle: 'Trusted by Our Candidates',
    trustSubtitle: 'Join a growing community of professionals succeeding in their job search with BazNova.',
    trustStats: 'Satisfied users',
    trustGuarantee: 'Our only goal is your satisfaction.',
