  legalCountryMorocco: 'Morocco',
  legalServiceTitle: '2. Service Description',
  legalServiceDesc: 'BazNova is an AI-assisted online resume and cover letter generation service, available in 4 languages (French, English, Arabic, Spanish) with 3 layout templates and 2 download formats (PDF, Word).',
  legalCguTitle: '3. General Terms of Use',
  legalCgu31Title: '3.1. Service Access',
  legalCgu31Desc: 'Access to the service requires creating an account and subscribing to a plan (Pro Plan or Lifetime Plan). The service is accessible immediately after payment via our payment partner: LemonSqueezy (EUR/USD, international bank card, PayPal, Apple Pay, Google Pay).',
  legalCgu32Title: '3.2. Authorized Use',
  legalCgu32Desc: 'The service is intended for legitimate personal and professional use. The user agrees not to use the service for unlawful, fraudulent purposes or purposes that infringe on the rights of third parties.',
  legalCgu33Title: '3.3. Intellectual Property',
  legalCgu33Desc: 'The name "BazNova", logo, design, source code and all content on the site are the exclusive property of E-Society 2050. Any reproduction, copying, modification, distribution or use of the service or its elements without prior written authorization is strictly prohibited and constitutes infringement punishable by law.',
  legalCgu34Title: '3.4. Generated Content',
  legalCgu34Desc: 'Resumes and cover letters generated by AI are the property of the user. BazNova claims no rights over content generated by its users.',
  legalCgu35Title: '3.5. Payments and Refunds',
  legalCgu35Desc: 'Payments are processed by our authorized payment partner: LemonSqueezy (EUR/USD). For any refund request, please contact support via the help button on the site.',
  legalCgu36Title: '3.6. Liability',
  legalCgu36Desc: 'BazNova provides a writing assistance tool. The quality of the final result depends on the information provided by the user. BazNova cannot be held responsible for the content of generated documents or their use by the user.',
  legalDataTitle: '4. Personal Data Protection',
  legalDataIntro: 'In accordance with Moroccan legislation (Law 09-08 on the protection of individuals with regard to the processing of personal data), we inform users that:',
  legalDataBullet1: 'Collected data (name, email, resume information) is used solely for the operation of the service.',
  legalDataBullet2: 'Data is never sold or shared with third parties.',
  legalDataBullet3: 'The user may request deletion of their data at any time by contacting support.',
  legalDataBullet4: 'Data is stored securely.',
  legalCopyrightTitle: '5. Copyright',
  legalCopyrightDesc: '© 2026 BazNova — E-Society 2050. All rights reserved. The "BazNova" brand and the entire service are protected by Moroccan and international intellectual property laws (Berne Convention). Any violation will be prosecuted.',
  legalHostingTitle: '6. Hosting',
  legalHostingDesc: 'The site is hosted by Vercel Inc., San Francisco, United States.',
  legalContactTitle: '7. Contact',
