    // SEO & FAQ
    seoTitle: 'الأسئلة الشائعة حول BazNova — السيرة الذاتية ورسالة التعريف ودرجة ATS',
    faqTitle: 'الأسئلة الشائعة',
    faqSubtitle: 'كل ما تحتاج معرفته عن BazNova وأدوات الذكاء الاصطناعي للبحث عن عمل.',
    faqQ1: 'كيف يعمل BazNova لإنشاء سيرة ذاتية؟',
    faqA1: 'يستخدم BazNova ذكاءً اصطناعيًا متقدمًا لتحليل معلوماتك المهنية وإنشاء سيرة ذاتية مخصصة. املأ النموذج في 4 خطوات، اختر القالب (عصري أو كلاسيكي أو إبداعي)، وسيقوم الذكاء الاصطناعي بكتابة سيرة ذاتية احترافية محسّنة لأنظمة ATS في أقل من 60 ثانية.',
    faqQ2: 'ما هي درجة ATS ولماذا هي مهمة؟',
    faqA2: 'درجة ATS (نظام تتبع المتقدمين) تقيس مدى توافق سيرتك الذاتية مع برامج التوظيف الآلية المستخدمة من قبل أكثر من 75% من الشركات. يحلل BazNova سيرتك على 5 معايير: الكلمات المفتاحية، الهيكل والتنسيق، الخبرة والتأثير، ملاءمة المهارات، وسهولة القراءة.',
    faqQ3: 'هل يمكنني إنشاء سيرة ذاتية بلغات متعددة؟',
    faqA3: 'نعم! BazNova متوفر بـ 4 لغات: الفرنسية والإنجليزية والعربية والإسبانية. يتكيف الذكاء الاصطناعي مع كل لغة من حيث المفردات والأسلوب والتنسيق.',
    faqQ4: 'كم يكلف BazNova؟',
    faqA4: 'يقدم BazNova 5 خطط مدفوعة: Starter بسعر 9€/شهر للطلاب، Pro بسعر 19€/شهر للباحثين النشطين عن عمل (الأكثر شعبية)، Career+ بسعر 39€/شهر للتنفيذيين (يشمل Mobility و Global)، Employer بسعر 49€/شهر للموظفين، و Enterprise بأسعار مخصصة للشركات الكبيرة. تتوفر أيضًا خطة سنوية بسعر 70€/سنة. تتيح الخطة المجانية اكتشاف الأداة مع 2 سير ذاتية/شهر. تتوفر واجهة برمجة تطبيقات REST للمطورين.',
    faqQ5: 'هل يمكنني تحميل سيرتي الذاتية بصيغة PDF و Word؟',
    faqA5: 'بالتأكيد! مع خطط Pro والسنوية، يمكنك تحميل سيرتك بصيغة PDF (A4 قياسي) و Word (.doc). كلا الصيغتين محسّنتان تمامًا للطباعة والمشاركة عبر البريد الإلكتروني.',
    faqQ6: 'كيف تعمل رسالة التعريف بالذكاء الاصطناعي؟',
    faqA6: 'ينشئ BazNova رسالة تعريف مخصصة من معلوماتك وعرض الوظيفة المستهدف. أدخل اسم الشركة والمسمى الوظيفي والوظيفة ودوافعك ونقاط قوتك. يكتب الذكاء الاصطناعي رسالة مقنعة ومناسبة للنبرة المختارة في 30 ثانية.',
    faqQ7: 'هل بياناتي الشخصية آمنة؟',
    faqA7: 'نعم، أمان بياناتك أولويتنا. معلوماتك مشفرة ولا تُشارك أبدًا مع أطراف ثالثة. نستخدم بروتوكولات أمان قياسية (HTTPS، تشفير البيانات). يمكنك حذف حسابك وجميع بياناتك في أي وقت.',
    faqQ8: 'هل يعمل BazNova للمرشحين الدوليين؟',
    faqA8: 'نعم! BazNova مصمم للمرشحين حول العالم. ندعم المدفوعات بـ EUR و USD و GBP. خدمتنا متاحة في 16 دولة عبر أوروبا والأمريكتين وأوقيانوسيا والخليج.',
