    // SEO & FAQ
    seoTitle: 'Preguntas frecuentes sobre BazNova — Currículum, Carta de Presentación y Puntuación ATS',
    faqTitle: 'Preguntas Frecuentes',
    faqSubtitle: 'Todo lo que necesitas saber sobre BazNova y nuestras herramientas IA para tu búsqueda de empleo.',
    faqQ1: '¿Cómo funciona BazNova para crear un currículum?',
    faqA1: 'BazNova utiliza inteligencia artificial avanzada para analizar tu información profesional y generar un currículum personalizado. Completa el formulario en 4 pasos, elige tu plantilla (Moderna, Clásica o Creativa), y la IA redacta un currículum profesional optimizado para ATS en menos de 60 segundos.',
    faqQ2: '¿Qué es la puntuación ATS y por qué es importante?',
    faqA2: 'La puntuación ATS (Applicant Tracking System) mide la compatibilidad de tu currículum con los software de reclutamiento automatizados utilizados por más del 75% de las empresas. BazNova analiza tu currículum en 5 criterios: palabras clave y SEO, estructura y formato, experiencia e impacto, adecuación de competencias, y legibilidad.',
    faqQ3: '¿Puedo crear un currículum en varios idiomas?',
    faqA3: '¡Sí! BazNova está disponible en 4 idiomas: francés, inglés, árabe y español. La IA adapta el vocabulario, el estilo y el formato a cada idioma.',
    faqQ4: '¿Cuánto cuesta BazNova?',
    faqA4: 'BazNova ofrece 5 planes de pago: Starter a 9€/mes para estudiantes, Pro a 19€/mes para buscadores activos (el más popular), Career+ a 39€/mes para ejecutivos (incluye Mobility y Global), Empleador a 49€/mes para reclutadores, y Enterprise con precio personalizado para grandes empresas. También hay un plan Anual a 70€/año. Un plan Gratis permite descubrir la herramienta con 2 currículums/mes. Una API REST está disponible para desarrolladores.',
    faqQ5: '¿Puedo descargar mi currículum en PDF y Word?',
    faqA5: '¡Por supuesto! Con los planes Pro y Anual, puedes descargar tu currículum en PDF (formato A4 estándar) y Word (.doc). Ambos formatos están perfectamente optimizados para impresión y compartir por email.',
    faqQ6: '¿Cómo funciona la carta de presentación con IA?',
    faqA6: 'BazNova genera una carta de presentación personalizada a partir de tu información y la oferta de empleo. Ingresa el nombre de la empresa, el puesto, tus motivaciones y puntos fuertes. La IA redacta una carta persuasiva adaptada al tono elegido en 30 segundos.',
    faqQ7: '¿Están seguros mis datos personales?',
    faqA7: 'Sí, la seguridad de tus datos es nuestra prioridad. Tu información está cifrada y nunca se comparte con terceros. Puedes eliminar tu cuenta y todos tus datos en cualquier momento.',
    faqQ8: '¿BazNova funciona para candidatos internacionales?',
    faqA8: '¡Sí! BazNova está diseñado para candidatos de todo el mundo. Aceptamos pagos en EUR, USD y GBP. Nuestro servicio está disponible en 16 países de Europa, Américas, Oceanía y el Golfo.',
    trustTitle: 'La confianza de Nuestros Candidatos',
    trustSubtitle: 'Únete a una comunidad creciente de profesionales que logran éxito en su búsqueda de empleo con BazNova.',
    trustStats: 'Usuarios satisfechos',
    trustGuarantee: 'Nuestro único objetivo es su satisfacción.',
