  legalServiceTitle: '2. Descripción del servicio',
  legalServiceDesc: 'BazNova es un servicio en línea de generación de currículums y cartas de presentación asistido por inteligencia artificial, disponible en 4 idiomas (francés, inglés, árabe, español) con 3 plantillas de diseño y 2 formatos de descarga (PDF, Word).',
  legalCguTitle: '3. Condiciones Generales de Uso',
  legalCgu31Title: '3.1. Acceso al servicio',
  legalCgu31Desc: 'El acceso al servicio requiere la creación de una cuenta y el pago de una suscripción (Plan Pro o Plan Lifetime). El servicio es accesible inmediatamente después del pago a través de nuestro socio de pago: LemonSqueezy (EUR/USD, tarjeta bancaria internacional, PayPal, Apple Pay, Google Pay).',
  legalCgu32Title: '3.2. Uso autorizado',
  legalCgu32Desc: 'El servicio está destinado a un uso personal y profesional legítimo. El usuario se compromete a no utilizar el servicio para fines ilícitos, fraudulentos o que vulneren los derechos de terceros.',
  legalCgu33Title: '3.3. Propiedad intelectual',
  legalCgu33Desc: 'El nombre "BazNova", el logotipo, el diseño, el código fuente y todo el contenido del sitio son propiedad exclusiva de E-Society 2050. Cualquier reproducción, copia, modificación, distribución o uso del servicio o de sus elementos sin autorización escrita previa está estrictamente prohibida y constituye una infracción punible por la ley.',
  legalCgu34Title: '3.4. Contenido generado',
  legalCgu34Desc: 'Los currículums y cartas de presentación generados por IA son propiedad del usuario. BazNova no reclama ningún derecho sobre el contenido generado por sus usuarios.',
  legalCgu35Title: '3.5. Pagos y reembolsos',
  legalCgu35Desc: 'Los pagos son procesados por nuestro socio de pago autorizado: LemonSqueezy (EUR/USD). Para cualquier solicitud de reembolso, por favor contacta al soporte a través del botón de ayuda en el sitio.',
  legalCgu36Title: '3.6. Responsabilidad',
  legalCgu36Desc: 'BazNova proporciona una herramienta de asistencia de redacción. La calidad del resultado final depende de la información proporcionada por el usuario. BazNova no se hace responsable del contenido de los documentos generados ni de su uso por parte del usuario.',
  legalDataTitle: '4. Protección de datos personales',
  legalDataIntro: 'De conformidad con la legislación marroquí (Ley 09-08 relativa a la protección de las personas físicas en relación con el tratamiento de datos personales), informamos a los usuarios que:',
  legalDataBullet1: 'Los datos recopilados (nombre, correo electrónico, información del currículum) se utilizan únicamente para el funcionamiento del servicio.',
  legalDataBullet2: 'Los datos nunca se venden ni se comparten con terceros.',
  legalDataBullet3: 'El usuario puede solicitar la eliminación de sus datos en cualquier momento contactando al soporte.',
  legalDataBullet4: 'Los datos se almacenan de forma segura.',
  legalCopyrightTitle: '5. Derechos de autor',
  legalCopyrightDesc: '© 2026 BazNova — E-Society 2050. Todos los derechos reservados. La marca "BazNova" y la totalidad del servicio están protegidos por las leyes marroquíes e internacionales de propiedad intelectual (Convenio de Berna). Cualquier violación será perseguida.',
  legalHostingTitle: '6. Alojamiento',
  legalHostingDesc: 'El sitio está alojado por Vercel Inc., San Francisco, Estados Unidos.',
  legalContactTitle: '7. Contacto',
  legalContactDesc: 'Para cualquier pregunta sobre estos avisos legales, por favor contacta a:',
