export function t(lang: CVLanguage, key: string): string {
  return (translations[lang] as Record<string, string>)?.[key]
    ?? (i18nExtensions[lang] as Record<string, string>)?.[key]
    ?? (translations.fr as Record<string, string>)[key]
    ?? (i18nExtensions.fr as Record<string, string>)?.[key]
    ?? key
}